//! Headless, single-account web server for LLM Wiki.
//!
//! Compiled *inside* the upstream lib (see `#[path]` in src-tauri/src/lib.rs)
//! so it can reach the crate-private `#[tauri::command]` functions through
//! the `__web_cmd_*` wrappers generated by the shim macro.
//!
//! Routes (all behind the session cookie except /api/auth/* and the login page):
//!   POST /api/invoke/:cmd     run a backend command with JSON args
//!   GET  /api/events          SSE stream of every backend `emit`
//!   POST /api/emit            frontend -> backend-bus event (rare)
//!   POST /api/store           tauri-plugin-store replacement
//!   ANY  /api/proxy           CORS-free outbound fetch (plugin-http replacement)
//!   POST /api/upload          browser file / folder upload into DATA_DIR/uploads
//!   GET  /api/asset?path=     file bytes (convertFileSrc replacement, Range aware)
//!   GET  /api/download?path=  same, as attachment
//!   GET  /api/fs/list         server-side folder picker
//!   POST /api/fs/mkdir
//!   ANY  /api/clip/*          -> internal clip server (127.0.0.1:19827)
//!   ANY  /api/local-api/*     -> internal REST API (127.0.0.1:19828, opt-in)
//!   GET  /*                   Vite dist (SPA fallback to index.html)

mod auth;
mod files;
mod http_proxy;
mod invoke;
mod paths;
mod store;

use std::net::SocketAddr;
use std::path::PathBuf;
use std::sync::Arc;

use axum::extract::{DefaultBodyLimit, Request, State};
use axum::http::{header, HeaderValue, Method, StatusCode};
use axum::middleware::{self, Next};
use axum::response::sse::{Event, KeepAlive, Sse};
use axum::response::{Html, IntoResponse, Redirect, Response};
use axum::routing::{any, get, post};
use axum::{Json, Router};
use futures::stream::Stream;
use serde_json::{json, Value};
use tauri::{AppHandle, Manager};

pub struct WebConfig {
    pub port: u16,
    pub bind: String,
    pub data_dir: PathBuf,
    pub app_data_dir: PathBuf,
    pub projects_dir: PathBuf,
    pub uploads_dir: PathBuf,
    pub exports_dir: PathBuf,
    pub dist_dir: PathBuf,
    pub resource_dir: PathBuf,
    pub allow_private_proxy: bool,
    pub allow_cli: bool,
    pub enable_api_server: bool,
    pub enable_clip_server: bool,
    pub max_upload_bytes: usize,
}

#[derive(Clone)]
pub struct AppState {
    pub app: AppHandle,
    pub cfg: Arc<WebConfig>,
    pub auth: Arc<auth::Auth>,
    pub stores: Arc<store::Stores>,
}

fn env_flag(name: &str, default: bool) -> bool {
    match std::env::var(name) {
        Ok(v) => matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes" | "on"),
        Err(_) => default,
    }
}

fn load_config() -> WebConfig {
    let data_dir = PathBuf::from(std::env::var("DATA_DIR").unwrap_or_else(|_| "/data".into()));
    std::fs::create_dir_all(&data_dir).expect("cannot create DATA_DIR");
    let data_dir = data_dir.canonicalize().expect("cannot resolve DATA_DIR");
    let exe_dir = std::env::current_exe()
        .ok()
        .and_then(|p| p.parent().map(|p| p.to_path_buf()))
        .unwrap_or_else(|| PathBuf::from("."));
    let dist_dir = std::env::var("DIST_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| {
            for c in [exe_dir.join("dist"), PathBuf::from("dist"), PathBuf::from("../dist")] {
                if c.join("index.html").is_file() {
                    return c;
                }
            }
            exe_dir.join("dist")
        });
    let dist_dir = dist_dir.canonicalize().unwrap_or(dist_dir);
    let resource_dir = std::env::var("RESOURCE_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| exe_dir.clone());
    let cfg = WebConfig {
        port: std::env::var("PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(7860),
        bind: std::env::var("BIND").unwrap_or_else(|_| "0.0.0.0".into()),
        app_data_dir: data_dir.join("app"),
        projects_dir: data_dir.join("projects"),
        uploads_dir: data_dir.join("uploads"),
        exports_dir: data_dir.join("exports"),
        data_dir,
        dist_dir,
        resource_dir,
        allow_private_proxy: env_flag("LLM_WIKI_PROXY_ALLOW_PRIVATE", false),
        allow_cli: env_flag("LLM_WIKI_ALLOW_CLI", false),
        enable_api_server: env_flag("LLM_WIKI_ENABLE_API_SERVER", false),
        enable_clip_server: env_flag("LLM_WIKI_ENABLE_CLIP_SERVER", true),
        max_upload_bytes: std::env::var("MAX_UPLOAD_MB")
            .ok()
            .and_then(|v| v.parse::<usize>().ok())
            .unwrap_or(512)
            * 1024
            * 1024,
    };
    for d in [
        &cfg.app_data_dir,
        &cfg.projects_dir,
        &cfg.uploads_dir,
        &cfg.exports_dir,
        &cfg.data_dir.join("home"),
    ] {
        let _ = std::fs::create_dir_all(d);
    }
    cfg
}

/// Entry point of the `llm-wiki-web` binary.
pub fn main() {
    let cfg = load_config();

    // Keep everything (HOME-relative caches, lancedb temp files, CLI configs,
    // ...) inside the single persistent volume. Done before any thread starts.
    if !env_flag("LLM_WIKI_KEEP_HOME", false) {
        let home = cfg.data_dir.join("home");
        std::env::set_var("HOME", &home);
        std::env::set_var("XDG_CONFIG_HOME", home.join(".config"));
        std::env::set_var("XDG_DATA_HOME", home.join(".local/share"));
        std::env::set_var("XDG_CACHE_HOME", home.join(".cache"));
    }
    let _ = std::env::set_current_dir(&cfg.data_dir);
    if std::env::var_os("PDFIUM_DYNAMIC_LIB_PATH").is_none() {
        for c in [
            cfg.resource_dir.join("libpdfium.so"),
            cfg.resource_dir.join("pdfium").join("libpdfium.so"),
        ] {
            if c.is_file() {
                std::env::set_var("PDFIUM_DYNAMIC_LIB_PATH", &c);
                break;
            }
        }
    }

    let rt = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .thread_name("llm-wiki-web")
        .build()
        .expect("tokio runtime");
    tauri::async_runtime::set_handle(rt.handle().clone());
    rt.block_on(serve(cfg));
}

fn init_app(cfg: &WebConfig) -> AppHandle {
    let app = AppHandle::new_headless(cfg.app_data_dir.clone(), cfg.resource_dir.clone());
    crate::commands::fs::set_resource_dir_hint(cfg.resource_dir.clone());

    let store_path = cfg.app_data_dir.join("app-state.json");
    if let Some(proxy_cfg) = crate::proxy::read_proxy_config_from_store(&store_path) {
        eprintln!("[proxy] {}", crate::proxy::apply_proxy_env(&proxy_cfg));
    }

    // Same managed state as the desktop `setup()` callback.
    app.manage(crate::commands::claude_cli::ClaudeCliState::default());
    app.manage(crate::commands::codex_cli::CodexCliState::default());
    app.manage(crate::commands::file_sync::FileSyncState::default());
    app.manage(crate::agent::session::AgentSessionStore::default());
    app.manage(crate::agent::cancel::AgentCancellationRegistry::default());
    app.manage(crate::CloseBehaviorState(std::sync::Mutex::new("minimize".to_string())));
    app.manage(crate::TrayAvailabilityState(std::sync::Mutex::new(false)));

    if cfg.enable_clip_server {
        crate::clip_server::start_clip_server(app.clone());
    }
    if cfg.enable_api_server {
        crate::api_server::start_api_server(app.clone());
    }
    app
}

async fn serve(cfg: WebConfig) {
    let app = init_app(&cfg);
    let cfg = Arc::new(cfg);
    let state = AppState {
        auth: Arc::new(auth::Auth::load(&cfg.data_dir)),
        stores: Arc::new(store::Stores::new(cfg.app_data_dir.clone())),
        app,
        cfg: cfg.clone(),
    };

    files::spawn_upload_janitor(cfg.uploads_dir.clone());

    let api = Router::new()
        .route("/api/invoke/{cmd}", post(invoke::handle_invoke))
        .route("/api/events", get(sse_events))
        .route("/api/emit", post(handle_emit))
        .route("/api/store", post(store::handle_store))
        .route("/api/proxy", any(http_proxy::handle_proxy))
        .route("/api/upload", post(files::handle_upload))
        .route("/api/asset", get(files::handle_asset))
        .route("/api/download", get(files::handle_download))
        .route("/api/fs/list", get(files::handle_fs_list))
        .route("/api/fs/mkdir", post(files::handle_fs_mkdir))
        .route("/api/web/config", get(handle_web_config))
        .route("/api/clip/{*rest}", any(http_proxy::handle_clip_forward))
        .route("/api/local-api/{*rest}", any(http_proxy::handle_local_api_forward))
        .route("/api/auth/password", post(auth::handle_change_password))
        .route("/api/{*rest}", any(api_not_found))
        .route_layer(middleware::from_fn_with_state(state.clone(), require_session));

    let public = Router::new()
        .route("/api/auth/status", get(auth::handle_status))
        .route("/api/auth/setup", post(auth::handle_setup))
        .route("/api/auth/login", post(auth::handle_login))
        .route("/api/auth/logout", post(auth::handle_logout))
        .route("/logout", get(auth::handle_logout_get))
        .route("/login", get(login_page));

    let static_files = tower_http::services::ServeDir::new(&cfg.dist_dir)
        .append_index_html_on_directories(true)
        .fallback(tower_http::services::ServeFile::new(cfg.dist_dir.join("index.html")));
    let spa = Router::new()
        .fallback_service(static_files)
        .layer(middleware::from_fn_with_state(state.clone(), require_session_page));

    let router = Router::new()
        .merge(api)
        .merge(public)
        .merge(spa)
        .layer(DefaultBodyLimit::max(cfg.max_upload_bytes))
        .layer(middleware::from_fn(security_headers))
        .with_state(state);

    let addr: SocketAddr = format!("{}:{}", cfg.bind, cfg.port)
        .parse()
        .expect("invalid BIND/PORT");
    eprintln!(
        "[web] LLM Wiki web server listening on http://{addr}  (DATA_DIR={}, dist={})",
        cfg.data_dir.display(),
        cfg.dist_dir.display()
    );
    if !cfg.dist_dir.join("index.html").is_file() {
        eprintln!("[web] WARNING: {} has no index.html — build the frontend with `npm run build:web`", cfg.dist_dir.display());
    }
    let listener = tokio::net::TcpListener::bind(addr).await.expect("bind failed");
    axum::serve(listener, router.into_make_service_with_connect_info::<SocketAddr>())
        .with_graceful_shutdown(async {
            let _ = tokio::signal::ctrl_c().await;
        })
        .await
        .expect("server error");
}

// ------------------------------------------------------------------ middleware

async fn security_headers(req: Request, next: Next) -> Response {
    let mut res = next.run(req).await;
    let h = res.headers_mut();
    h.entry(header::X_CONTENT_TYPE_OPTIONS)
        .or_insert(HeaderValue::from_static("nosniff"));
    h.entry("referrer-policy")
        .or_insert(HeaderValue::from_static("same-origin"));
    res
}

/// API guard: valid session cookie + (for state-changing methods) the
/// `X-LLM-Wiki` header, which cross-site forms cannot set (CSRF guard
/// that still works when the cookie has to be SameSite=None, e.g. inside
/// the Hugging Face Spaces iframe).
async fn require_session(State(st): State<AppState>, req: Request, next: Next) -> Response {
    if !st.auth.request_has_session(req.headers()) {
        return (StatusCode::UNAUTHORIZED, Json(json!({"error": "unauthorized"}))).into_response();
    }
    let m = req.method().clone();
    if m != Method::GET && m != Method::HEAD && m != Method::OPTIONS && !req.headers().contains_key("x-llm-wiki") {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error": "missing X-LLM-Wiki header"})),
        )
            .into_response();
    }
    next.run(req).await
}

/// Page guard: unauthenticated visitors get the login / first-run page.
async fn require_session_page(State(st): State<AppState>, req: Request, next: Next) -> Response {
    if st.auth.request_has_session(req.headers()) {
        return next.run(req).await;
    }
    let path = req.uri().path();
    // Let the browser fetch favicons etc. without leaking app content.
    if path == "/favicon.ico" {
        return StatusCode::NOT_FOUND.into_response();
    }
    if path.starts_with("/api/") {
        return (StatusCode::UNAUTHORIZED, Json(json!({"error": "unauthorized"}))).into_response();
    }
    Redirect::to("/login").into_response()
}

async fn login_page(State(st): State<AppState>, headers: axum::http::HeaderMap) -> Response {
    if st.auth.request_has_session(&headers) {
        return Redirect::to("/").into_response();
    }
    let mut res = Html(include_str!("login.html")).into_response();
    res.headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
    res
}

// ------------------------------------------------------------------ events

async fn sse_events(
    State(st): State<AppState>,
) -> Sse<impl Stream<Item = Result<Event, std::convert::Infallible>>> {
    use tokio_stream::wrappers::{errors::BroadcastStreamRecvError, BroadcastStream};
    use tokio_stream::StreamExt;
    let rx = st.app.subscribe_events();
    let hello = futures::stream::once(async {
        Ok::<_, std::convert::Infallible>(Event::default().event("ready").data("{}"))
    });
    let stream = BroadcastStream::new(rx).filter_map(|item| match item {
        Ok(ev) => {
            let data = json!({"event": ev.event, "payload": ev.payload}).to_string();
            Some(Ok(Event::default().data(data)))
        }
        Err(BroadcastStreamRecvError::Lagged(n)) => {
            eprintln!("[web] SSE client lagged, dropped {n} events");
            None
        }
    });
    Sse::new(futures::StreamExt::chain(hello, stream))
        .keep_alive(KeepAlive::new().interval(std::time::Duration::from_secs(15)))
}

async fn handle_emit(State(st): State<AppState>, Json(body): Json<Value>) -> impl IntoResponse {
    let event = body.get("event").and_then(Value::as_str).unwrap_or("").to_string();
    if event.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "event required"})));
    }
    st.app
        .emit_value(&event, body.get("payload").cloned().unwrap_or(Value::Null));
    (StatusCode::OK, Json(json!({"ok": true})))
}

async fn api_not_found() -> Response {
    (StatusCode::NOT_FOUND, Json(json!({"error": "no such API endpoint"}))).into_response()
}

async fn handle_web_config(State(st): State<AppState>) -> Json<Value> {
    let c = &st.cfg;
    Json(json!({
        "web": true,
        "version": env!("CARGO_PKG_VERSION"),
        "dataDir": c.data_dir,
        "projectsDir": c.projects_dir,
        "uploadsDir": c.uploads_dir,
        "exportsDir": c.exports_dir,
        "passwordFromEnv": st.auth.password_from_env(),
        "allowCli": c.allow_cli,
        "apiServerEnabled": c.enable_api_server,
    }))
}
